 boolean route(World w,int center,boolean water){int minX=center-130,maxX=center+130,minZ=-90,maxZ=90;java.util.Set<Long> seen=new HashSet<>();java.util.ArrayDeque<int[]> queue=new java.util.ArrayDeque<>();queue.add(new int[]{center-20,55});while(!queue.isEmpty()){int[] point=queue.remove();int x=point[0],z=point[1];long key=((long)x<<32)^(z&0xffffffffL);if(!seen.add(key)||x<minX||x>maxX||z<minZ||z>maxZ)continue;var floor=w.getBlockAt(x,64,z);if(water?floor.getType()!=Material.WATER:!floor.getType().isSolid()&&floor.getType()!=Material.WATER)continue;if(!w.getBlockAt(x,65,z).isPassable()||!w.getBlockAt(x,66,z).isPassable())continue;for(int[] delta:new int[][]{{1,0},{-1,0},{0,1},{0,-1}})queue.add(new int[]{x+delta[0],z+delta[1]});}for(int[] gate:new int[][]{{center+45,55},{center+102,0},{center+45,-55},{center-45,-55},{center-102,0},{center-45,55}})if(!seen.contains(((long)gate[0]<<32)^(gate[1]&0xffffffffL)))return false;return true;}
 Object enumValue(Object previous,String value){return Enum.valueOf((Class)previous.getClass(),value);}
 Object member(Object plugin,Player p)throws Exception{return ((Map<?,?>)get(plugin,"membership")).get(p.getUniqueId());}
 Object get(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 void set(Object target,String name,Object value)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);f.set(target,value);}
 Object call(Object target,String name,Object... args)throws Exception{Method m=Arrays.stream(target.getClass().getDeclaredMethods()).filter(x->x.getName().equals(name)&&x.getParameterCount()==args.length).filter(x->{for(int i=0;i<args.length;i++)if(args[i]!=null&&!x.getParameterTypes()[i].isPrimitive()&&!x.getParameterTypes()[i].isInstance(args[i]))return false;return true;}).findFirst().orElseThrow();m.setAccessible(true);return m.invoke(target,args);}
